    let exiled_id = state.get_object(object_id)
        .and_then(|o| o.card_state.get("exiled_creature").copied());
    if let Some(target_id) = exiled_id {
        if state.get_object(target_id).map(|o| o.zone == Zone::Exile).unwrap_or(false) {
